"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5755],{23933:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"","params":[{"name":"clock","desc":"Defaults to `os.time`. Pass a closure over a local for full control.","lua_type":"Clock?"}],"returns":[{"desc":"","lua_type":"InMemoryStore\\n"}],"function_type":"static","source":{"line":61,"path":"src/stores/InMemory.luau"}},{"name":"failNext","desc":"Makes the next `count` calls to `operation` fail, as a store outage would.\\n\\nOperation names are the method names: `get`, `set`, `update`, `remove`,\\n`sortedSet`, `sortedRemove`, `sortedRange`.","params":[{"name":"self","desc":"","lua_type":"InMemoryStore"},{"name":"operation","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":80,"path":"src/stores/InMemory.luau"}},{"name":"conflictNext","desc":"Makes the next `count` updates lose a compare-and-set race.\\n\\nThe transform runs once against the value it read, that result is discarded,\\n`mutator` installs a competing write, and the transform runs again against\\nthe new value \u2014 which is what `UpdateAsync` does under contention.\\n\\nThis is what catches a transform that fails to reset its own bookkeeping when\\nre-entered, which every conditional write in Muster depends on.","params":[{"name":"self","desc":"","lua_type":"InMemoryStore"},{"name":"operation","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number?"},{"name":"mutator","desc":"Receives the current value and returns the competing writer\'s value. Omit to re-run against unchanged state.","lua_type":"((any) -> any)?"}],"returns":[],"function_type":"static","source":{"line":97,"path":"src/stores/InMemory.luau"}},{"name":"callCount","desc":"Calls made, for one operation or in total. Muster\'s suite asserts against\\nthis to keep its request budget from regressing.","params":[{"name":"self","desc":"","lua_type":"InMemoryStore"},{"name":"operation","desc":"","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":286,"path":"src/stores/InMemory.luau"}}],"properties":[],"types":[],"name":"InMemoryStore","desc":"A complete [Store] backed by tables, with a synthetic clock, working TTL\\nexpiry, call counting and fault injection.\\n\\nMuster\'s own suite runs against it, and it ships publicly so consumers can\\ntest without MemoryStore, Studio, or real time passing.\\n\\n```lua\\nlocal now = 0\\nlocal store = Muster.stores.InMemory.new(function() return now end)\\n\\nlocal queue = Muster.new({\\n\\tname = \\"test\\", size = 2,\\n\\tstore = store, clock = function() return now end,\\n\\tautoStart = false, broadcast = false,\\n})\\n\\nqueue:enqueue(1)\\nqueue:enqueue(2)\\nqueue:step()          -- matched, deterministically, with no yielding\\n\\nnow += 200            -- everything expires exactly like it would live\\n```\\n\\n[InMemoryStore:failNext] and [InMemoryStore:conflictNext] inject the two\\nfailure modes worth testing against.","source":{"line":32,"path":"src/stores/InMemory.luau"}}')}}]);